<script setup lang="ts">
import { computed, ref } from 'vue'
import LabFrame from './LabFrame.vue'
import { useLabPlayback } from './useLabPlayback'
const root = ref<HTMLElement | null>(null)
const frame = ref(0)
const chunks = ['先读取','当前项目，','再添加','轻松档。']
const received = computed(() => Math.max(0,Math.min(4,Math.floor((frame.value-9)/2))))
const status = computed(() => frame.value < 3 ? '组织请求' : frame.value < 6 ? '发送' : frame.value < 8 ? '验证凭据' : frame.value < 10 ? '处理消息' : frame.value < 18 ? '逐段返回' : '完成')
useLabPlayback(root, () => { frame.value++; return frame.value < 20 }, 550, { reset: () => { frame.value = 0 }, static: () => { frame.value = 20 } })
</script>
<template>
  <div ref="root" class="api-envelope" :data-demo-frame="frame" :data-chunks="received">
    <LabFrame title="发出一句话，接回一个回答" hint="DSH 将消息与地址、凭据、模型配置组织为请求；服务验证并处理，回答分段返回到同一对话。这里只模拟数据流，不发送真实请求。">
      <div class="lab-stage api-stage">
        <div class="api-conversation">
          <div class="chat-heading"><i class="ti ti-message" aria-hidden="true" /><span>DSH</span><span class="chat-status">{{ status }}</span></div>
          <div class="chat-user">给贪吃蛇加个慢速档</div>
          <div class="request-config" :class="{ packed: frame >= 3 }"><span><i class="ti ti-world" aria-hidden="true" />地址</span><span><i class="ti ti-key" aria-hidden="true" />凭据</span><span><i class="ti ti-cpu" aria-hidden="true" />模型</span></div>
          <div class="chat-answer" :class="{ visible: frame >= 10 }"><i class="ti ti-sparkles" aria-hidden="true" /><div><span v-for="(chunk,i) in chunks" :key="chunk" class="answer-chunk" :class="{ arrived: received > i }">{{ chunk }}</span><span v-if="received < 4" class="answer-caret" /></div></div>
          <div class="chat-finish" :class="{ visible: frame >= 18 }"><i class="ti ti-check" aria-hidden="true" />响应已接收</div>
        </div>
        <div class="api-exchange" :class="{ returning: frame >= 10 }" aria-hidden="true"><span class="exchange-track" /><span class="exchange-packet" :style="{ transform: `translateX(${frame < 3 ? 0 : frame < 6 ? (frame-3)*30 : frame < 10 ? 90 : 90-(frame-10)%3*30}px)`, opacity: frame >= 3 && frame < 18 ? 1 : 0 }"><i :class="['ti',frame >= 10 ? 'ti-align-left' : 'ti-send']" /></span></div>
        <div class="api-service" :class="{ connected: frame >= 6 }"><div class="service-orbit"><span class="service-ring" :style="{ transform: `rotate(${frame*18}deg)` }"><i /></span><i class="ti ti-server service-icon" aria-hidden="true" /><span class="service-check" :class="{ visible: frame >= 8 }"><i class="ti ti-check" aria-hidden="true" /></span></div><span class="service-name">模型服务</span><span class="service-detail">{{ frame >= 8 ? '凭据通过' : frame >= 6 ? '验证中' : '等待请求' }}</span><div class="service-chunks" aria-hidden="true"><span v-for="i in 4" :key="i" :class="{ sent: received >= i }" /></div></div>
      </div>
    </LabFrame>
  </div>
</template>
<style scoped>
