.service-ring { position: absolute; inset: 4px; border: 1px solid var(--mag-hairline); border-radius: 50%; transition: transform .55s linear; }.service-ring > i { position: absolute; top: 10px; left: 12px; width: 6px; height: 6px; border-radius: 50%; background: var(--mag-hairline-strong); }.service-icon { font-size: 38px; color: var(--lab-muted); }.connected .service-icon,.connected .service-ring > i { color: var(--lab-blue); }.connected .service-ring { border-color: var(--mag-accent-border); }.connected .service-ring > i { background: var(--lab-blue); }.service-check { position: absolute; right: 9px; bottom: 7px; display: grid; place-items: center; width: 22px; height: 22px; background: var(--lab-paper); border: 1px solid var(--mag-accent-border); border-radius: 50%; color: var(--lab-blue); opacity: 0; }.service-name { margin-top: 12px; font-size: 13px; }.service-detail { font-size: 11px; color: var(--lab-muted); margin-top: 4px; }.service-chunks { display: flex; gap: 5px; margin-top: 16px; }.service-chunks span { width: 12px; height: 4px; background: var(--mag-hairline); transition: background .3s; }.service-chunks .sent { background: var(--lab-blue); }.visible { opacity: 1; }@media(max-width:560px) { .api-stage { grid-template-columns: minmax(0,1fr) 86px; gap: 14px; }.api-exchange { display: none; }.service-orbit { width: 80px; height: 80px; }.service-icon { font-size: 28px; }.service-ring > i { top: 6px; left: 8px; }.service-check { right: 0; bottom: 2px; }.request-config { gap: 8px; flex-wrap: wrap; }.chat-heading { flex-wrap: wrap; }.chat-status { width: 100%; margin-left: 0; }.chat-user { font-size: 12px; padding: 8px 10px; }.chat-answer { font-size: 13px; gap: 6px; }.api-stage { padding-inline: 16px; } }
